import { GoPanic } from "@gotots/runtime/panic.js";
import { Seq } from "../iter/sequence.js";
export function Copy(targetMap, sourceMap, copyKey, copyValue, target, source) {
    const targetValue = targetMap(target);
    const sourceValue = sourceMap(source);
    for (const key of sourceValue.keys()) {
        targetValue.store(copyKey(key), copyValue(sourceValue.lookup(key)));
    }
}
export function Clone(resultMap, sourceMap, copyKey, copyValue, makeMap, zeroValue, source) {
    const sourceValue = sourceMap(source);
    if (sourceValue.isNil()) {
        return source;
    }
    const result = makeMap(zeroValue());
    for (const key of sourceValue.keys()) {
        result.store(copyKey(key), copyValue(sourceValue.lookup(key)));
    }
    return resultMap(result);
}
export function Equal(leftMap, rightMap, equal, left, right) {
    const leftValue = leftMap(left);
    const rightValue = rightMap(right);
    if (leftValue.length() !== rightValue.length()) {
        return false;
    }
    for (const key of leftValue.keys()) {
        const [candidate, present] = rightValue.lookupOk(key);
        if (!present || !equal(leftValue.lookup(key), candidate)) {
            return false;
        }
    }
    return true;
}
export function EqualFunc(leftMap, rightMap, copyLeft, copyRight, left, right, equal) {
    if (equal === undefined) {
        GoPanic.raiseRuntime("invalid memory address or nil pointer dereference");
    }
    const leftValue = leftMap(left);
    const rightValue = rightMap(right);
    if (leftValue.length() !== rightValue.length()) {
        return false;
    }
    for (const key of leftValue.keys()) {
        const [candidate, present] = rightValue.lookupOk(key);
        if (!present
            || !equal(copyLeft(leftValue.lookup(key)), copyRight(candidate))) {
            return false;
        }
    }
    return true;
}
export function Keys(sourceMap, copyKey, source) {
    const sourceValue = sourceMap(source);
    return new Seq((yieldValue) => {
        if (yieldValue === undefined) {
            GoPanic.raiseRuntime("invalid memory address or nil pointer dereference");
        }
        for (const key of sourceValue.keys()) {
            if (!yieldValue(copyKey(key))) {
                return;
            }
        }
    });
}
export function Values(sourceMap, copyValue, source) {
    const sourceValue = sourceMap(source);
    return new Seq((yieldValue) => {
        if (yieldValue === undefined) {
            GoPanic.raiseRuntime("invalid memory address or nil pointer dereference");
        }
        for (const key of sourceValue.keys()) {
            if (!yieldValue(copyValue(sourceValue.lookup(key)))) {
                return;
            }
        }
    });
}
